import { GetAllTagsResponse, TagSchema } from "../types/schema/tag.js";
import { http } from "../utils/http.js";
const endpoint = 'tags';
/** Creates a new tag. */
export async function createTag(requestOptions) {
  const response = await http(requestOptions, {
    method: 'post',
    url: endpoint,
    responseType: 'json'
  });
  return TagSchema.parse(response.data);
}
/** Fetches all tags in a paginated manner. */
export async function getAllTags(requestOptions, options) {
  const response = await http(requestOptions, {
    url: endpoint,
    params: {
      offset: options?.offset,
      limit: options?.limit
    },
    responseType: 'json'
  });
  return GetAllTagsResponse.parse(response.data).tags;
}
/** Retrieves tag information from the Bee node. */
export async function getTag(requestOptions, uid) {
  const response = await http(requestOptions, {
    url: `${endpoint}/${uid}`,
    responseType: 'json'
  });
  return TagSchema.parse(response.data);
}
/** Deletes a tag. */
export async function deleteTag(requestOptions, uid) {
  await http(requestOptions, {
    method: 'delete',
    url: `${endpoint}/${uid}`
  });
}
/** Updates a tag's total chunks count. */
export async function updateTag(requestOptions, uid, reference) {
  await http(requestOptions, {
    method: 'patch',
    url: `${endpoint}/${uid}`,
    data: {
      reference
    }
  });
}